// migrationProxyKey returns the UID string used to look up the migration proxy
// listeners for the VMI.
//
// For a decentralized migration target using the UNIX transport, the target's
// virt-launcher opens its migration sockets keyed by the source VMI's UID (since
// the source and target VMIs are distinct objects). In that case the source VMI
// UID from MigrationState.SourceState is returned. In every other case (non-UNIX
// transport, or missing migration/source state) the VMI's own UID is used.
func migrationProxyKey(vmi *v1.VirtualMachineInstance) string {
	if vmi.IsMigrationTarget() &&
		vmi.Status.MigrationTransport == v1.MigrationTransportUnix &&
		vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.SourceState != nil &&
		vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID != nil {
		return string(*vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID)
	}
	return string(vmi.UID)
