// migrationTargetShouldWaitForSync reports whether a VMI that is acting as a
// decentralized migration target should move to (or stay in) the WaitingForSync
// phase rather than transitioning to Failed/Scheduling. This happens when the
// migration on the target side has ended: either the migration has been marked
// failed and completed, or the target pod has reached a terminal (Failed or
// Succeeded) state. Waiting for sync lets the source side coordinate the outcome
// instead of the target independently failing the VMI.
func migrationTargetShouldWaitForSync(vmi *virtv1.VirtualMachineInstance, vmiPodExists bool, pod *k8sv1.Pod) bool {
	if !vmi.IsMigrationTarget() {
		return false
	}
	if vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.Failed &&
		vmi.Status.MigrationState.Completed {
		return true
	}
	return vmiPodExists && pod != nil && isPodFinal(pod)
